def transform(grid):
    g = np.array(grid)
    out = g.copy()
    d = dividers(g)
    divcols = set(c for _, c in d["rows"]) | set(c for _, c in d["cols"])
    boxes = panels(g)
    ys = sorted(set(b[0] for b in boxes))
    xs = sorted(set(b[1] for b in boxes))

    def key_colour(b):
        p = crop(g, *b)
        vals = [v for v in np.unique(p) if v not in (0, 1) and v not in divcols]
        return vals[0] if vals else None

    for b in boxes:
        p = crop(g, *b)
        if not (p == 1).any():
            continue
        col = None
        # same panel-row first
        for o in boxes:
            if o != b and o[0] == b[0]:
                k = key_colour(o)
                if k is not None:
                    col = k
                    break
        # otherwise same panel-column
        if col is None:
            for o in boxes:
                if o != b and o[1] == b[1]:
                    k = key_colour(o)
                    if k is not None:
                        col = k
                        break
        if col is None:
            continue
        y0, x0, y1, x1 = b
        region = out[y0:y1 + 1, x0:x1 + 1]
        region[g[y0:y1 + 1, x0:x1 + 1] == 1] = col
        emit(out, f"Recolour the 1-shape in panel {b} with key colour {col} from its aligned key panel.")
    emit(out, "All pattern panels recoloured; final grid.")
    return out
